#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1 << 19 | 5;
int n, k, p, sizeLimit, popCount[MAXN], arr[MAXN];
int bucket1[20][MAXN], bucket2[20][MAXN], bucket3[20][MAXN];
long long mod2;
long long helper[20][MAXN];
long long fact[MAXN], invFact[MAXN];

long long power(long long base, long long exp) {
    long long res = 1, cur = base;
    while (exp) {
        if (exp & 1) res = res * cur % p;
        cur = cur * cur % p;
        exp >>= 1;
    }
    return res;
}

void factorialInit() {
    fact[0] = 1;
    for (int i = 1; i <= sizeLimit; i++) fact[i] = fact[i - 1] * i % p;
    invFact[sizeLimit] = power(fact[sizeLimit], p - 2);
    for (int i = sizeLimit - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % p;
}

int nextPowerOfTwoMinusOne(int x) {
    int tmp = 1;
    while (tmp < x) tmp <<= 1;
    return tmp - 1;
}

void FWT(int *a, int len, bool inverse = false) {
    long long *tmpArr = helper[0];
    for (int i = 0; i < len; i++) tmpArr[i] = a[i];
    if (inverse) {
        for (int step = 1; step < len; step <<= 1)
            for (int i = 0; i < len; i += (step << 1))
                for (int j = i; j < i + step; j++)
                    tmpArr[j + step] -= tmpArr[j];
    } else {
        for (int step = 1; step < len; step <<= 1)
            for (int i = 0; i < len; i += (step << 1))
                for (int j = i; j < i + step; j++)
                    tmpArr[j + step] += tmpArr[j];
    }
    for (int i = 0; i < len; i++) {
        a[i] = tmpArr[i] % p;
        if (a[i] < 0) a[i] += p;
    }
}

inline void reduce(long long &val) {
    if (val >= mod2) val -= mod2;
}

void convolutionWithArr() {
    for (int j = 0; j <= 19; j++) {
        fill(bucket1[j], bucket1[j] + sizeLimit + 1, 0);
        fill(helper[j], helper[j] + sizeLimit + 1, 0);
    }
    for (int j = 0; j <= sizeLimit; j++) bucket1[popCount[j]][j] = arr[j];
    for (int j = 0; j <= 19; j++) FWT(bucket1[j], sizeLimit + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= sizeLimit; s++)
                reduce(helper[q + l][s] += 1LL * bucket1[q][s] * bucket2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= sizeLimit; s++)
            bucket3[q][s] = helper[q][s] % p;
    for (int j = 0; j <= 19; j++) FWT(bucket3[j], sizeLimit + 1, true);
    for (int j = 0; j <= sizeLimit; j++) arr[j] = bucket3[popCount[j]][j];
}

void convolutionWithSelf() {
    static int temp[20][MAXN];
    for (int i = 0; i <= 19; i++) fill(helper[i], helper[i] + sizeLimit + 1, 0);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= sizeLimit; s++)
                reduce(helper[q + l][s] += 1LL * bucket2[q][s] * bucket2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= sizeLimit; s++)
            temp[q][s] = helper[q][s] % p;
    for (int i = 0; i <= 19; i++) FWT(temp[i], sizeLimit + 1, true);
    for (int i = 0; i <= 19; i++) fill(bucket2[i], bucket2[i] + sizeLimit + 1, 0);
    for (int i = 0; i <= sizeLimit; i++) bucket2[popCount[i]][i] = temp[popCount[i]][i];
    for (int i = 0; i <= 19; i++) FWT(bucket2[i], sizeLimit + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    mod2 = 1LL * p * p;
    if (n & 1) {
        printf("%lld", power(k, n));
        return 0;
    }
    arr[0] = 1;
    sizeLimit = nextPowerOfTwoMinusOne(n + 1);
    factorialInit();
    for (int i = 0; i <= sizeLimit; i++) popCount[i] = __builtin_popcount(i);
    for (int i = 0; i <= sizeLimit; i++) bucket2[popCount[i]][i] = invFact[i];
    for (int i = 0; i <= 19; i++) FWT(bucket2[i], sizeLimit + 1);
    int originalK = k;
    while (k) {
        cerr << k << endl;
        if (k & 1) convolutionWithArr();
        k >>= 1;
        if (k) convolutionWithSelf();
    }
    printf("%lld", (power(originalK, n) - fact[n] * arr[n] % p + p) % p);
    return 0;
}
